-- Phase 3a, migration B: every PlanSession change in one migration.
--
-- Generated by `prisma migrate diff`, then edited by hand in the INSERT of the redefine only:
--   * "externalId" is required with no default, so each existing row gets its own random uuid
--     (version 4 layout) from SQLite's randomblob(), which is evaluated once per row.
--   * "trimmed" is backfilled from "rules": true when the rule id design-4.3 is in the JSON list.
--     The quotes make the match exact, so design-4.30 would not count.
-- Every other column is copied as it is, "activityId" included, so session links to activities
-- survive. The foreign keys are off for the redefine (the PRAGMAs below) and nothing references
-- PlanSession, so no cascade or set-null fires while the table is dropped.

-- RedefineTables
PRAGMA defer_foreign_keys=ON;
PRAGMA foreign_keys=OFF;
CREATE TABLE "new_PlanSession" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "planId" TEXT NOT NULL,
    "externalId" TEXT NOT NULL,
    "weekStart" TEXT NOT NULL,
    "date" TEXT NOT NULL,
    "order" INTEGER NOT NULL,
    "kind" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "durationMin" INTEGER NOT NULL,
    "distanceM" INTEGER,
    "gainM" INTEGER,
    "structure" TEXT NOT NULL DEFAULT '[]',
    "target" TEXT NOT NULL,
    "purpose" TEXT NOT NULL,
    "rules" TEXT NOT NULL DEFAULT '[]',
    "trimmed" BOOLEAN NOT NULL DEFAULT false,
    "flags" TEXT NOT NULL DEFAULT '[]',
    "status" TEXT NOT NULL DEFAULT 'planned',
    "activityId" TEXT,
    "linkSource" TEXT,
    "execution" TEXT,
    "original" TEXT,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "PlanSession_planId_fkey" FOREIGN KEY ("planId") REFERENCES "Plan" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "PlanSession_activityId_fkey" FOREIGN KEY ("activityId") REFERENCES "Activity" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
INSERT INTO "new_PlanSession" ("activityId", "date", "distanceM", "durationMin", "execution", "externalId", "flags", "gainM", "id", "kind", "linkSource", "order", "original", "planId", "purpose", "rules", "status", "structure", "target", "title", "trimmed", "updatedAt", "weekStart")
SELECT
    "activityId",
    "date",
    "distanceM",
    "durationMin",
    "execution",
    lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', 1 + (random() & 3), 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6))),
    "flags",
    "gainM",
    "id",
    "kind",
    "linkSource",
    "order",
    "original",
    "planId",
    "purpose",
    "rules",
    "status",
    "structure",
    "target",
    "title",
    instr("rules", '"design-4.3"') > 0,
    "updatedAt",
    "weekStart"
FROM "PlanSession";
DROP TABLE "PlanSession";
ALTER TABLE "new_PlanSession" RENAME TO "PlanSession";
CREATE UNIQUE INDEX "PlanSession_activityId_key" ON "PlanSession"("activityId");
CREATE INDEX "PlanSession_planId_date_idx" ON "PlanSession"("planId", "date");
CREATE INDEX "PlanSession_planId_weekStart_trimmed_idx" ON "PlanSession"("planId", "weekStart", "trimmed");
CREATE INDEX "PlanSession_planId_status_date_idx" ON "PlanSession"("planId", "status", "date");
CREATE UNIQUE INDEX "PlanSession_planId_externalId_key" ON "PlanSession"("planId", "externalId");
PRAGMA foreign_keys=ON;
PRAGMA defer_foreign_keys=OFF;

-- CreateIndex
CREATE INDEX "Activity_duplicateOfId_idx" ON "Activity"("duplicateOfId");

-- CreateIndex
CREATE INDEX "PlanRevision_planId_reason_idx" ON "PlanRevision"("planId", "reason");
